import{z as B,x as d,o,c as p,q as E,j as i,D as e,d as l,s as r,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"剂量-焦深耦合","description":"","frontmatter":{"title":"剂量-焦深耦合","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dose-focus-coupling.md","filePath":"litho/dose-focus-coupling.md","lastUpdated":1791063341000}'),u={name:"litho/dose-focus-coupling.md"};function D(h,a,m,A,g,C){const t=d("Mermaid");return o(),p("div",null,[a[2]||(a[2]=E('<h1 id="剂量-焦深耦合" tabindex="-1">剂量-焦深耦合 <a class="header-anchor" href="#剂量-焦深耦合" aria-label="Permalink to &quot;剂量-焦深耦合&quot;">​</a></h1><div class="epigraph"><p>剂量轴上的 $\\mathrm{CD}(E)$ 与焦轴上的 Bossung 不是两次独立实验：离焦掉 NILS，同一相对剂量误差会走出更大的 CD，窗在两个方向同时收。</p><footer>—— 据 Mack 对 E–D 窗口与 Bossung；胶核如何改弯曲的讨论整理</footer></div><p><a href="/litho/dose-to-size">上一课</a>在最佳焦附近画出 \\(\\mathrm{CD}(E)\\)。<a href="/litho/bossung-curve">Bossung 曲线</a>与 <a href="/litho/ed-process-window">E–D 窗口</a>在主干已经把两轴画在一起。缺口是胶这一侧：反应–扩散与显影如何让剂量与焦深耦，而不是再推一次 \\(\\lambda/\\mathrm{NA}^2\\)。本课钉耦合。显影后热流另起炉灶，留给<a href="/litho/resist-reflow">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光学上，离焦使空中像调制变浅，阈值处 ILS 下降。剂量一漂，边走得更远——所以 Bossung 族在离焦端散开。胶的 \\(\\gamma\\) 高、\\(\\ell\\) 大，都是在已经变浅的潜像上再乘一道：有效 NILS 更低，同样的离焦走出更弯的 CD。耦合因此是乘法，不是「先光学后胶各报各的窗再取最小」。</p><p><span class="marginnote">NILS（归一化图像对数斜率）翻译成大白话就是「边缘有多陡」：数值越大，剂量或离焦的小扰动在 CD 上引起的晃动越小。初学者容易以为剂量窗和焦深窗是两个独立验收项、各测各的取最小就行；实际上是乘法——离焦先把像变缓，剂量误差再被这条缓边放大。</span></p><p><span class="marginnote">数字实例：最佳焦处空中像 NILS=2，离焦后掉到 1.2，胶的化学衰减再乘 0.8，有效 NILS 只剩约 1。此时剂量每偏 1%，CD 约偏 1%；不离焦时同样 1% 剂量误差只引起约 0.5% 的 CD 变化——耦合把剂量敏感度放大了一倍。</span></p><p>缺口不是重画 E–D 面积，而是：改 PEB、改淬灭、改胶厚，Bossung 弯曲会变，即使镜头没动。把焦深规格写成纯光学 \\(k_2\\)，会把轨道超差判成扫描机失焦。</p><h3 id="等焦剂量会被胶搬走" tabindex="-1">等焦剂量会被胶搬走 <a class="header-anchor" href="#等焦剂量会被胶搬走" aria-label="Permalink to &quot;等焦剂量会被胶搬走&quot;">​</a></h3><p>主干 Bossung 课指出等焦附近 CD 对 \\(z\\) 不敏感。化学阈值切点随 \\(E_0\\)、负载、\\(\\gamma\\) 移动时，等焦对应的剂量跟着走。密线与孤立线的等焦差，一部分来自光学 OPE，一部分来自胶核对不同空间频率的衰减不同。RET 换照明改前一项；换 PEB 改后一项。</p><p><span class="marginnote">不要在本课重导瑞利焦深公式。尺度仍是 \\(\\propto\\lambda/\\mathrm{NA}^2\\)；本课只问胶如何改「还活着的那块面积」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：完整曝光–散焦矩阵，而不是只扫剂量或只扫焦。比较「只改 PEB」与「只改照明」两张 Bossung：前者弯曲形态变、最佳焦可能微移（轴向吸收与剖面）；后者调制结构变。模拟：同一 TCC，换胶核，应能复现弯曲差——这是 LPM / 轮廓仿真的签核，不是光学课的签核。</p><p>High-NA 胶厚与 DOF 已经挤在同一预算里，见<a href="/litho/high-na-resist-budget">胶厚预算</a>。耦合在薄膜上更狠：膜顶膜底不在同一焦面，剂量清底与焦面选择绑死。</p>',14)),(o(),i(n,null,{default:e(()=>[r(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E7%A6%BB%E7%84%A6%20%E2%86%92%20NILS%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20COUP%5B%22%E6%9C%89%E6%95%88%E6%96%9C%E7%8E%87%22%5D%0A%20%20GAMMA%5B%22%CE%B3%20%E4%B8%8E%20%E2%84%93%22%5D%20--%3E%20COUP%0A%20%20COUP%20--%3E%20BOSS%5B%22Bossung%20%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20E%5B%22%E5%89%82%E9%87%8F%22%5D%20--%3E%20BOSS%0A%20%20BOSS%20--%3E%20ED%5B%22E-D%20%E9%9D%A2%E7%A7%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[l("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"潜像强度可看成空中像经化学核卷积。离焦改空中像，核改卷积后的边。剂量改切在卷积后剖线的哪一条等高线。三条一起决定 CD。核越宽，离焦造成的对比损失越被「已经很糊」掩盖，有时弯曲看起来变平——那不是焦深变好，是分辨率已经交出去，等焦假象。Mack 警告过：平的 Bossung 不等于高 NILS。",-1)),a[5]||(a[5]=s("p",null,[s("span",{class:"marginnote"},"Bossung 曲线可以想象成一张等高线地图：横轴剂量、纵轴焦距，每个点报出一个 CD，把相同 CD 的点连成线。最佳剂量就是那条最平的谷线；离焦等于从谷线往坡上走，同样一步滑得更远。")],-1)),a[6]||(a[6]=s("p",null,"吸收沿 \\(z\\) 不均匀时，最佳焦随剂量走（dose-focus 倾斜）：过剂量更吃底部或顶部，视漂白与衰减方向而定。Dill \\(A\\)、\\(B\\) 在这里进入焦轴，薄膜课的 \\(I(z)\\) 变成 Bossung 的不对称。",-1)),(o(),i(n,null,{default:e(()=>[r(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22Dill%20A%2FB%20%E6%B2%BF%E8%86%9C%E5%8E%9A%E5%90%B8%E6%94%B6%E4%B8%8D%E5%9D%87%22%5D%20--%3E%20IZ%5B%22%E9%A1%B6%E9%83%A8%E4%B8%8E%E5%BA%95%E9%83%A8%20I(z)%20%E4%B8%8D%E5%90%8C%22%5D%0A%20%20DOSE%5B%22%E5%89%82%E9%87%8F%E5%A2%9E%E5%87%8F%22%5D%20--%3E%20IZ%0A%20%20IZ%20--%3E%20CUT%5B%22%E6%98%BE%E5%BD%B1%E5%88%87%E7%82%B9%E6%B2%BF%20z%20%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20CUT%20--%3E%20TILT%5B%22%E6%9C%80%E4%BD%B3%E7%84%A6%E9%9A%8F%E5%89%82%E9%87%8F%E5%80%BE%E6%96%9C%22%5D%0A%20%20TILT%20--%3E%20ASYM%5B%22Bossung%20%E6%97%8F%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">矢量成像改 \\(I\\) 本身，耦合定义不变。偏振课不在这里重开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某代机台的焦深验收表写进胶规格。随机缺陷会在平均 E–D 窗内部先切一刀，那是后一单元的随机工艺窗口。下一课热回流发生在显影之后，不改曝光时的剂量–焦耦合，但会改最终 CD 对烘箱的敏感，看起来像「又一条焦轴」——物理是黏度，不要并进本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离焦掉 ILS，胶的 \\(\\gamma\\) 与 \\(\\ell\\) 再乘，Bossung 弯曲是耦合结果。</li><li>改 PEB / 淬灭 / 厚会改焦窗，即使镜头未动。</li><li>等焦剂量随化学切点走；平曲线可能是核过糊。</li><li>Dill 吸收造成剂量–最佳焦倾斜。</li><li>出处：Mack 对 Bossung 与 E–D；主干窗口课。</li></ul>',5))])}const S=B(u,[["render",D]]);export{c as __pageData,S as default};
